import org.junit.jupiter.api.Test;
import org.junit.Assert;
import org.iets3.core.expr.base.plugin.InterpreterSession;
import java.util.List;
import jetbrains.mps.internal.collections.runtime.ListSequence;
import java.util.ArrayList;

public class InterpreterSessionLifecycle_Test {
  @Test
  public void test_nestedSessionsShareTheOuterOne() throws Exception {
    Assert.assertEquals("no session is open before the test", true, InterpreterSession.current() == null);
    final InterpreterSession outer = InterpreterSession.open();
    try {
      Assert.assertEquals("open() makes the new session current", true, InterpreterSession.current() == outer);
      Assert.assertEquals("open() inside a session returns null", true, InterpreterSession.open() == null);
      InterpreterSession seenInside = InterpreterSession.withSession(() -> InterpreterSession.current());
      Assert.assertEquals("withSession inside a session runs in the outer one", true, seenInside == outer);
      Assert.assertEquals("withSession leaves the outer session open", true, InterpreterSession.current() == outer);
    } finally {
      outer.close();
    }
    Assert.assertEquals("close() ends the session on this thread", true, InterpreterSession.current() == null);
  }
  @Test
  public void test_cachedComputesOncePerSession() throws Exception {
    final List<String> computed = ListSequence.fromList(new ArrayList<String>());
    InterpreterSession session = InterpreterSession.open();
    try {
      Object first = session.cached("key", () -> {
        ListSequence.fromList(computed).addElement("key");
        return "value";
      });
      Object second = session.cached("key", () -> {
        ListSequence.fromList(computed).addElement("key");
        return "other";
      });
      Assert.assertEquals("the second lookup of a key returns the first value", true, first == second);
      Assert.assertEquals("the value of a key is computed once", 1, ListSequence.fromList(computed).count());
    } finally {
      session.close();
    }
  }
  @Test
  public void test_closeRunsEveryActionDespiteFailures() throws Exception {
    final List<String> ran = ListSequence.fromList(new ArrayList<String>());
    InterpreterSession session = InterpreterSession.open();
    session.onClose(() -> ListSequence.fromList(ran).addElement("first"));
    session.onClose(() -> {
      throw new InjectedFailure("second failed");
    });
    session.onClose(() -> {
      ListSequence.fromList(ran).addElement("third");
      throw new IllegalStateException("third failed");
    });
    try {
      session.close();
      Assert.fail("close() rethrows the first failure of its close actions");
    } catch (IllegalStateException e) {
      Assert.assertEquals("the first failure, in the reverse order of registration, is rethrown", "third failed", e.getMessage());
      Assert.assertEquals("later failures are added as suppressed", 1, e.getSuppressed().length);
      Assert.assertEquals("an Error of a close action is kept as suppressed", true, e.getSuppressed()[0] instanceof InjectedFailure);
    }
    Assert.assertEquals("every close action runs, in the reverse order of registration", ListSequence.fromListAndArray(new ArrayList<String>(), "third", "first"), ran);
    Assert.assertEquals("close() ends the session also when actions fail", true, InterpreterSession.current() == null);
  }
}
